<script setup lang="ts">
import {withoutPmsLoader} from './loading';import PmsMyWorkAssignees from './PmsMyWorkAssignees.vue';import {ref,onMounted,onUnmounted} from 'vue';import {pmsApi} from './api';import PmsTaskDetail from './PmsTaskDetail.vue';import PmsSprintBoard from './PmsSprintBoard.vue';import PmsFormDialog from './PmsFormDialog.vue';import PmsDescriptionEditor from './PmsDescriptionEditor.vue';
const emit=defineEmits(['create-project']);const quickAssignment=ref<any>(null);const props=defineProps<{csrf?:string;permissions:string[];initialDepartment?:number|null}>();const dragged=ref<number|null>(null),data=ref<any>(null),board=ref<any>(null),department=ref<any>(null),project=ref(''),workflow=ref(''),sprint=ref('all'),issue=ref<number|null>(null),issueAction=ref(''),busy=ref(false),error=ref(''),task=ref<any>(null),taskWorkflow=ref<any>(null),taskWorkflowBusy=ref(false);let taskWorkflowVersion=0;
async function open(d:any){department.value=d;busy.value=true;try{const url=new URL(location.href);url.searchParams.set('section','team-space');url.searchParams.set('department',String(d.id));for(const [key,value]of Object.entries({project:project.value,workflow:workflow.value,sprint:sprint.value})){if(value)url.searchParams.set(key,value);else url.searchParams.delete(key);}history.replaceState(null,'',url);board.value=(await pmsApi('team-space/'+d.id+'?'+new URLSearchParams({project:project.value,workflow:workflow.value,sprint:sprint.value}))).data;error.value='';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function drop(c:any){if(!dragged.value||busy.value)return;const id=dragged.value;dragged.value=null;busy.value=true;try{const result=await pmsApi('tasks/'+id+'/board',props.csrf,'PATCH',{status:c.id});const resultTask=result.task;const existing=board.value.boardTasks.find((t:any)=>t.id===id);if(existing&&resultTask)Object.assign(existing,resultTask);}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
function showIssue(id:number,action=''){if(action==='assign'&&Array.isArray(board.value?.asignee)){const t=board.value.boardTasks.find((t:any)=>t.id===id);if(t){quickAssignment.value=t;return;}}issue.value=id;issueAction.value=action;}
async function taskProject(){const version=++taskWorkflowVersion;taskWorkflow.value=null;task.value.sprint_id='';task.value.workflow_id='';task.value.workflow_column_id='';if(!task.value.project_id)return;taskWorkflowBusy.value=true;try{const response=await withoutPmsLoader(()=>pmsApi('projects/'+task.value.project_id));if(version!==taskWorkflowVersion||!task.value)return;taskWorkflow.value=response.data.selectedWorkflow;task.value.workflow_id=taskWorkflow.value?.id;task.value.workflow_column_id=taskWorkflow.value?.columns[0]?.id;}catch(e){error.value=(e as Error).message;}finally{if(version===taskWorkflowVersion)taskWorkflowBusy.value=false;}}function newTask(){task.value={title:'',description:'',project_id:Number(project.value)||'',workflow_id:board.value.selectedWorkflow?.id,workflow_column_id:board.value.selectedWorkflow?.columns[0]?.id,status:'pending',priority:1,sprint_id:'',assignee_ids:[],due_date:'',attachments:[]};void taskProject();}
async function create(values:any,done:()=>void){busy.value=true;try{const f=new FormData();for(const [key,value] of Object.entries(values)){if(Array.isArray(value))value.forEach(v=>f.append(key+'[]',v instanceof File?v:String(v)));else if(value!==''&&value!=null)f.append(key,String(value));}await pmsApi('tasks',props.csrf,'POST',f);done();await open(department.value);}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function quickCreate(title:string,done:()=>void,projectId:string,sprintId:string){if(!projectId){error.value='Select a department project first.';return;}await create({title,project_id:projectId,status:'pending',sprint_id:sprintId||''},done);}
function liveUpdate(){if(!busy.value&&!task.value&&!issue.value&&!quickAssignment.value&&board.value&&department.value)void open(department.value);}onMounted(async()=>{window.addEventListener('pms:changed',liveUpdate);try{data.value=await pmsApi('team-space');const q=new URLSearchParams(location.search);project.value=q.get('project')||'';sprint.value=q.get('sprint')||'all';workflow.value=q.get('workflow')||'';const selected=data.value.departments.find((d:any)=>d.id===(props.initialDepartment||Number(q.get('department'))));if(selected)await open(selected);const id=Number(q.get('issue'));if(id>0)issue.value=id;}catch(e){error.value=(e as Error).message;}});onUnmounted(()=>window.removeEventListener('pms:changed',liveUpdate));
</script>
<template><p v-if="error" class="notice admin-error" role="alert">{{error}}</p><template v-if="!board"></template><template v-else><PmsSprintBoard v-if="board.workflows" :data="board" :department="department" :permissions="permissions" :busy="busy" :project-filter="project" :workflow-filter="workflow" :sprint-filter="sprint" @project="project=$event;sprint='all';open(department)" @workflow="workflow=$event;open(department)" @sprint="sprint=$event;open(department)" @create="newTask" @quick-create="quickCreate" @open="showIssue($event)" @edit="showIssue($event,'edit')" @assign="showIssue($event,'assign')" @handoff="showIssue($event,'handoff')" @place="showIssue($event,'place')" @delete="showIssue($event,'delete')" @drag="dragged=$event" @drop="drop($event)"/><div v-else class="department-empty-shell"><section class="department-empty-card"><div class="department-empty-icon"><i class="ti ti-folders-off" aria-hidden="true"></i></div><div class="text-uppercase text-primary fw-semibold small mb-2">Team Space / {{department.dept_name}}</div><h3 class="mb-2">No projects in this department yet</h3><p class="text-muted">Create the first project for {{department.dept_name}}. Its sprints and tasks will then appear on this department board.</p><div class="d-flex justify-content-center gap-2"><button v-if="permissions.includes('*')||permissions.includes('project-add')" class="button primary" @click="emit('create-project',department.id)">Create project</button><a class="button" href="/pms?section=projects">View projects</a></div></section></div></template><PmsFormDialog v-if="task" title="Create issue" wide @close="task=null"><form class="pms-reference-form" @submit.prevent="create(task,()=>task=null)"><label class="full-width">Project <span class="text-danger">*</span><select v-model="task.project_id" @change="taskProject" required><option value="">Choose a department project</option><option v-for="p in board.departmentProjects" :key="p.id" :value="p.id">{{p.name}}</option></select><small>The new task will belong to the selected project.</small></label><label class="full-width">Summary<input v-model="task.title" required maxlength="255"></label><label class="full-width">Description<PmsDescriptionEditor v-model="task.description"/></label><label>Workflow column<select v-model="task.workflow_column_id" :disabled="taskWorkflowBusy||!taskWorkflow"><option v-for="c in taskWorkflow?.columns" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Priority<select v-model="task.priority"><option v-for="(label,i) in ['Low','Normal','High','Urgent']" :key="i" :value="i">{{label}}</option></select></label><label>Assignees<select v-model="task.assignee_ids" multiple size="4"><option v-for="p in board.asignee" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>Sprint<select v-model="task.sprint_id"><option value="">Backlog</option><option v-for="s in board.sprints?.filter((s:any)=>s.project_id==task.project_id)" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>Due date<input v-model="task.due_date" type="datetime-local"></label><label>Attachments<input type="file" multiple @change="task.attachments=Array.from(($event.target as HTMLInputElement).files||[])"></label><div class="editor-actions"><button class="button" type="button" @click="task=null">Cancel</button><button class="button primary" :disabled="busy||taskWorkflowBusy">Create issue</button></div></form></PmsFormDialog><PmsMyWorkAssignees v-if="quickAssignment" :task="quickAssignment" :users="board.asignee" :csrf="csrf" @close="quickAssignment=null" @updated="Object.assign(quickAssignment,$event)"/><PmsTaskDetail v-if="issue" :id="issue" :initial-action="issueAction" :csrf="csrf" :permissions="permissions" @close="issue=null;issueAction=''" @updated="open(department)"/></template>
